Definition apb_cells (w : Z) : list (Z * nat * Z) :=
  [(0x11d208, 8%nat, 0x10b414); (0x11d210, 8%nat, 0x105c88); (0x11d340, 8%nat, 0x10d778); (0x11d348, 8%nat, 0x10db7c);
   (0x129478, 8%nat, 0x7fff8000); (0x12a158, 1%nat, 1); (0x12a159, 1%nat, 1); (0x1baffc, 1%nat, 1);
   (0x11fd20, 4%nat, 5);          (* [comment removed for export] *)
   (0x11fd40, 8%nat, 0x67dfc0);   (* [comment removed for export] *)
   (0x11fd48, 8%nat, w);          (* [comment removed for export] *)
   (0x11fd80, 8%nat, 1024);       (* [comment removed for export] *)
   (0x11fdac, 4%nat, 0xffffffff); (* [comment removed for export] *)
   (0x11fdb0, 4%nat, 0xffffffff); (* [comment removed for export] *)
   (0x7fffaa48, 8%nat, 0); (0x7fffaa50, 8%nat, 0); (0x800c7b78, 8%nat, 0)]%Z.   (* [comment removed for export] *)

Record apbH (mem : word -> option byte) (sp : word) (w can : Z) : Prop := APBH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : ASP_LO <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= ASP_HI;
  Pstk   : stk_ok RSEGS mem sp 3400;
  Pimg   : forall i, 0x10000 <= i < 0x4d000 -> mem (Z_to_bv 64 i) = None;
  Pgot   : forall i, 0x115000 <= i < 0x11d000 -> mem (Z_to_bv 64 i) = None;
  Pcells : cells_ok mem (apb_cells w);
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0x67d4f0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64;
  Psh0   : forall a, 2147450880 + (bv_unsigned sp - 4096) / 8 <= a < 2147450880 + bv_unsigned sp / 8 ->
             mem (Z_to_bv 64 a) = Some (Z_to_bv 8 0) }.

Definition apb_post (regs : bvmap 5 word) (mem rom : word -> option byte) (sp : word) (w : Z) : Prop :=
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0x0a3128) mem rom) (mkst regs' (Z_to_bv 64 0x0a307c) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400); (Z_to_bv 64 0x11fd20, 4);
                          (Z_to_bv 64 0x11fd48, 8); (Z_to_bv 64 w, 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 w) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x11fd48) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (w + 2)))
    /\ rdn RSEGS mem' (Z_to_bv 64 0x11fd20) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5)).

