Definition resP0 := Eval vm_compute in (apb_run 0x67dbc0).
Definition carP0 := Eval vm_compute in (carry (s_log (fst (fst resP0))) (apb_kn 0x67dbc0) []).
Definition resP1 := Eval vm_compute in (apb_run 0x67dbc2).
Definition carP1 := Eval vm_compute in (carry (s_log (fst (fst resP1))) (apb_kn 0x67dbc2) []).
Definition resP2 := Eval vm_compute in (apb_run 0x67dbc4).
Definition carP2 := Eval vm_compute in (carry (s_log (fst (fst resP2))) (apb_kn 0x67dbc4) []).

Ltac run_case res car :=
  lazymatch goal with
  | PH : apbH ?mem ?sp ?w ?can, Hw : _, R1 : getr ?regs 1 = _, R2 : getr _ 2 = _, R11 : getr _ 11 = _ |- apb_post _ _ ?rom _ _ =>
      eapply (apb_case regs mem rom sp w can PH Hw R1 R2 R11
                (fst (fst res)) (snd (fst res)) (snd res) (fst (fst car)) (snd car));
      [ vm_cast_no_check (@eq_refl _ res)
      | reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_cast_no_check (@eq_refl _ car)
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity ]
  end.

Lemma apb_case0 : forall regs mem rom sp can,
  apbH mem sp 0x67dbc0 can ->
  getr regs 1 = Z_to_bv 64 0x0a307c -> getr regs 2 = sp -> getr regs 11 = Z_to_bv 64 0 ->
  apb_post regs mem rom sp 0x67dbc0.
Proof. intros regs mem rom sp can PH R1 R2 R11. assert (Hw : 0x67dbc0 <= 0x67dbc0 <= 0x67dbc4) by lia. run_case resP0 carP0. Qed.

Lemma apb_case1 : forall regs mem rom sp can,
  apbH mem sp 0x67dbc2 can ->
  getr regs 1 = Z_to_bv 64 0x0a307c -> getr regs 2 = sp -> getr regs 11 = Z_to_bv 64 0 ->
  apb_post regs mem rom sp 0x67dbc2.
Proof. intros regs mem rom sp can PH R1 R2 R11. assert (Hw : 0x67dbc0 <= 0x67dbc2 <= 0x67dbc4) by lia. run_case resP1 carP1. Qed.

Lemma apb_case2 : forall regs mem rom sp can,
  apbH mem sp 0x67dbc4 can ->
  getr regs 1 = Z_to_bv 64 0x0a307c -> getr regs 2 = sp -> getr regs 11 = Z_to_bv 64 0 ->
  apb_post regs mem rom sp 0x67dbc4.
Proof. intros regs mem rom sp can PH R1 R2 R11. assert (Hw : 0x67dbc0 <= 0x67dbc4 <= 0x67dbc4) by lia. run_case resP2 carP2. Qed.

