Theorem aprintf0_buffered : forall (j : nat) regs mem rom (sp : word) (can : Z),
  (j <= 2)%nat ->
  apbH mem sp (ABUF + 2 * Z.of_nat j) can ->
  getr regs 1 = Z_to_bv 64 0x0a307c -> getr regs 2 = sp -> getr regs 11 = Z_to_bv 64 0 ->
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0x0a3128) mem rom) (mkst regs' (Z_to_bv 64 0x0a307c) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400); (Z_to_bv 64 0x11fd20, 4);
                          (Z_to_bv 64 0x11fd48, 8); (Z_to_bv 64 (ABUF + 2 * Z.of_nat j), 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 (ABUF + 2 * Z.of_nat j)) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x11fd48) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (ABUF + 2 * Z.of_nat j + 2)))
    /\ rdn RSEGS mem' (Z_to_bv 64 0x11fd20) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5)).
Proof.
  intros j regs mem rom sp can Hj PH R1 R2 R11. unfold ABUF in *.
  destruct j as [|[|[|j]]]; [ | | | lia].
  - change (0x67dbc0 + 2 * Z.of_nat 0) with 0x67dbc0 in *. exact (apb_case0 regs mem rom sp can PH R1 R2 R11).
  - change (0x67dbc0 + 2 * Z.of_nat 1) with 0x67dbc2 in *. exact (apb_case1 regs mem rom sp can PH R1 R2 R11).
  - change (0x67dbc0 + 2 * Z.of_nat 2) with 0x67dbc4 in *. exact (apb_case2 regs mem rom sp can PH R1 R2 R11).
Qed.

